messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Low-Poly Treadmill Animation</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background-color: #222;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// --- Scene setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.Fog(0x87CEEB, 10, 40);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(0, 2, 8);
camera.lookAt(0, 0, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// --- Lights ---
const ambient = new THREE.AmbientLight(0xffffff, 0.5);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffffff, 1);
dirLight.position.set(5, 10, 5);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 1024;
dirLight.shadow.mapSize.height = 1024;
scene.add(dirLight);

// --- Ground (treadmill-style) ---
const groundGeo = new THREE.PlaneGeometry(10, 20);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.8 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.2;
ground.receiveShadow = true;
scene.add(ground);

// Add treadmill belt lines
const beltGeo = new THREE.PlaneGeometry(10, 20);
const beltMat = new THREE.MeshBasicMaterial({ color: 0x333333 });
const belt = new THREE.Mesh(beltGeo, beltMat);
belt.rotation.x = -Math.PI / 2;
belt.position.y = -0.21;
scene.add(belt);

// Draw dashed line on belt
const dashMat = new THREE.LineBasicMaterial({ color: 0xcccccc });
const dashGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-5, 0, 0),
  new THREE.Vector3(5, 0, 0)
]);
const dashLine = new THREE.Line(dashGeo, dashMat);
dashLine.rotation.x = -Math.PI / 2;
dashLine.position.y = -0.205;
scene.add(dashLine);

// --- Low-Poly Humanoid Builder ---
function createHumanoid() {
  const group = new THREE.Group();

  // Materials
  const skinMat = new THREE.MeshStandardMaterial({ color: 0xffd1b3, roughness: 0.6 });
  const shirtMat = new THREE.MeshStandardMaterial({ color: 0x2e8b57, roughness: 0.6 });
  const pantsMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });

  // Torso (capsule-ish)
  const torsoGeo = new THREE.CylinderGeometry(0.35, 0.4, 0.8, 6);
  const torso = new THREE.Mesh(torsoGeo, shirtMat);
  torso.position.y = 1.1;
  torso.castShadow = true;
  group.add(torso);

  // Head
  const headGeo = new THREE.SphereGeometry(0.25, 6, 6);
  const head = new THREE.Mesh(headGeo, skinMat);
  head.position.y = 1.65;
  head.castShadow = true;
  group.add(head);

  // Arms (upper + lower)
  const armGeo = new THREE.CylinderGeometry(0.08, 0.08, 0.5, 6);
  const upperArm = new THREE.Mesh(armGeo, skinMat);
  upperArm.position.set(0.35, 1.3, 0);
  upperArm.castShadow = true;
  group.add(upperArm);

  const lowerArm = new THREE.Mesh(armGeo, skinMat);
  lowerArm.position.set(0.35, 0.6, 0);
  lowerArm.castShadow = true;
  group.add(lowerArm);

  const upperArmL = new THREE.Mesh(armGeo, skinMat);
  upperArmL.position.set(-0.35, 1.3, 0);
  upperArmL.castShadow = true;
  group.add(upperArmL);

  const lowerArmL = new THREE.Mesh(armGeo, skinMat);
  lowerArmL.position.set(-0.35, 0.6, 0);
  lowerArmL.castShadow = true;
  group.add(lowerArmL);

  // Legs (upper + lower)
  const legGeo = new THREE.CylinderGeometry(0.12, 0.12, 0.5, 6);
  const upperLeg = new THREE.Mesh(legGeo, pantsMat);
  upperLeg.position.set(0.05, 0.4, 0);
  upperLeg.castShadow = true;
  group.add(upperLeg);

  const lowerLeg = new THREE.Mesh(legGeo, pantsMat);
  lowerLeg.position.set(0.05, -0.15, 0);
  lowerLeg.castShadow = true;
  group.add(lowerLeg);

  const upperLegL = new THREE.Mesh(legGeo, pantsMat);
  upperLegL.position.set(-0.05, 0.4, 0);
  upperLegL.castShadow = true;
  group.add(upperLegL);

  const lowerLegL = new THREE.Mesh(legGeo, pantsMat);
  lowerLegL.position.set(-0.05, -0.15, 0);
  lowerLegL.castShadow = true;
  group.add(lowerLegL);

  // Feet
  const footGeo = new THREE.BoxGeometry(0.3, 0.12, 0.2);
  const leftFoot = new THREE.Mesh(footGeo, skinMat);
  leftFoot.position.set(0.05, -0.35, 0);
  leftFoot.castShadow = true;
  group.add(leftFoot);

  const rightFoot = new THREE.Mesh(footGeo, skinMat);
  rightFoot.position.set(-0.05, -0.35, 0);
  rightFoot.castShadow = true;
  group.add(rightFoot);

  return {
    group,
    upperArm, lowerArm,
    upperArmL, lowerArmL,
    upperLeg, lowerLeg,
    upperLegL, lowerLegL,
    leftFoot, rightFoot,
    torso, head
  };
}

const humanoid = createHumanoid();
scene.add(humanoid.group);

// --- Animation State ---
let t = 0;
let phase = 0; // 0: stand, 1: walk, 2: run, 3: stand
let phaseTime = 0;
let walkTime = 0;
let runTime = 0;
let runLean = 0;

// --- Update function ---
function update(dt) {
  t += dt;

  // Phase durations
  const STAND = 2.0;
  const WALK = 3.0;
  const RUN = 3.0;

  if (phase === 0) {
    phaseTime += dt;
    if (phaseTime >= STAND) {
      phaseTime = 0;
      phase = 1;
    }
  } else if (phase === 1) {
    walkTime += dt;
    if (walkTime >= WALK) {
      walkTime = 0;
      phase = 2;
    }
  } else if (phase === 2) {
    runTime += dt;
    if (runTime >= RUN) {
      runTime = 0;
      phase = 3;
    }
  } else {
    phaseTime += dt;
    if (phaseTime >= STAND) {
      phaseTime = 0;
      phase = 0;
    }
  }

  // Normalize times to [0,1] for each phase
  const walkNorm = walkTime / WALK;
  const runNorm = runTime / RUN;

  // --- Limb animation helpers ---
  const lerp = (a, b, n) => a + (b - a) * n;
  const easeIn = x => x * x;
  const easeInOut = x => x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;

  // Walking (side-on, small swings)
  function walkAnim(norm) {
    // pelvis bob
    const pelvisBob = Math.sin(norm * Math.PI * 2) * 0.03;
    humanoid.torso.position.y = 1.1 + pelvisBob;

    // arms swing opposite to legs
    const armSwing = Math.sin(norm * Math.PI * 2) * 0.15;
    humanoid.upperArm.rotation.z = armSwing;
    humanoid.lowerArm.rotation.z = armSwing;
    humanoid.upperArmL.rotation.z = -armSwing;
    humanoid.lowerArmL.rotation.z = -armSwing;

    // legs
    const legSwing = Math.sin(norm * Math.PI * 2) * 0.18;
    humanoid.upperLeg.rotation.x = legSwing;
    humanoid.lowerLeg.rotation.x = legSwing;
    humanoid.upperLegL.rotation.x = -legSwing;
    humanoid.lowerLegL.rotation.x = -legSwing;

    // feet
    const footLift = Math.sin(norm * Math.PI * 2) * 0.12;
    humanoid.leftFoot.position.y = -0.35 + footLift;
    humanoid.rightFoot.position.y = -0.35 - footLift;
  }

  // Running (faster, larger swings, forward lean)
  function runAnim(norm) {
    // pelvis bob larger
    const pelvisBob = Math.sin(norm * Math.PI * 2) * 0.04;
    humanoid.torso.position.y = 1.1 + pelvisBob;

    // forward lean varies with run norm
    runLean = lerp(0, 0.15, runNorm);
    humanoid.group.rotation.x = -runLean;

    // arms swing bigger and faster
    const armSwing = Math.sin(norm * Math.PI * 2) * 0.28;
    humanoid.upperArm.rotation.z = armSwing;
    humanoid.lowerArm.rotation.z = armSwing;
    humanoid.upperArmL.rotation.z = -armSwing;
    humanoid.lowerArmL.rotation.z = -armSwing;

    // legs
    const legSwing = Math.sin(norm * Math.PI * 2) * 0.28;
    humanoid.upperLeg.rotation.x = legSwing;
    humanoid.lowerLeg.rotation.x = legSwing;
    humanoid.upperLegL.rotation.x = -legSwing;
    humanoid.lowerLegL.rotation.x = -legSwing;

    // feet
    const footLift = Math.sin(norm * Math.PI * 2) * 0.16;
    humanoid.leftFoot.position.y = -0.35 + footLift;
    humanoid.rightFoot.position.y = -0.35 - footLift;
  }

  // --- Apply phase animations ---
  if (phase === 1) {
    walkAnim(walkNorm);
  } else if (phase === 2) {
    runAnim(runNorm);
  } else {
    // Stand still: reset rotations and positions
    humanoid.group.rotation.set(0, 0, 0);
    humanoid.torso.position.y = 1.1;
    humanoid.upperArm.rotation.z.set(0, 0, 0);
    humanoid.lowerArm.rotation.z.set(0, 0, 0);
    humanoid.upperArmL.rotation.z.set(0, 0, 0);
    humanoid.lowerArmL.rotation.z.set(0, 0, 0);
    humanoid.upperLeg.rotation.x.set(0, 0, 0);
    humanoid.lowerLeg.rotation.x.set(0, 0, 0);
    humanoid.upperLegL.rotation.x.set(0, 0, 0);
    humanoid.lowerLegL.rotation.x.set(0, 0, 0);
    humanoid.leftFoot.position.y.set(-0.35, -0.35, 0);
    humanoid.rightFoot.position.y.set(-0.35, -0.35, 0);
  }
}

// --- Resize handler ---
function onResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
}
window.addEventListener('resize', onResize);

// --- Animation loop ---
const clock = new THREE.Clock();
requestAnimationFrame(() => {
  const dt = Math.min(clock.getDelta(), 0.1);
  update(dt);
  renderer.render(scene, camera);
});
</script>
</body>
</html>
```
